package net.civeira.phylax.features.access.userprofile.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AddressJsonVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property address json of user profile ")
  void test_address_json_v_o_builder() {
    Assertions.assertFalse(AddressJsonVO.nullValue().getAddressJson().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(AddressJsonVO.tryFrom(null).getAddressJson().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", AddressJsonVO.from("one").getAddressJson().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> AddressJsonVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", AddressJsonVO.from("one").toString());
  }
}
